<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {purchaseApi} from '@/api/purchases'
import type {Supplier} from '@/api/purchases'
const rows=ref<Supplier[]>([]),loading=ref(false),search=ref(''),error=ref(''),show=ref(false),editing=ref<number|null>(null)
const blank=()=>({name:'',company_name:'',email:'',phone:'',tax_number:'',address:'',city:'',country:'Bangladesh',notes:'',is_active:true})
const form=ref(blank())
async function load(){loading.value=true;error.value='';try{const r=await purchaseApi.suppliers({search:search.value||undefined});rows.value=r.data.data}catch(e:any){error.value=e?.response?.data?.message||'Could not load suppliers.'}finally{loading.value=false}}
function create(){editing.value=null;form.value=blank();show.value=true}
function edit(s:Supplier){editing.value=s.id;form.value={...s};show.value=true}
async function save(){try{if(editing.value)await purchaseApi.updateSupplier(editing.value,form.value);else await purchaseApi.createSupplier(form.value);show.value=false;await load()}catch(e:any){error.value=e?.response?.data?.message||'Could not save supplier.'}}
onMounted(load)
</script>
<template><section class="page"><header><div><small>SUPPLIER DIRECTORY</small><h1>Suppliers</h1><p>Manage vendors that supply your inventory.</p></div><button @click="create">＋ Add supplier</button></header><p v-if="error" class="error">{{error}}</p><div class="card"><div class="filters"><input v-model="search" @input="load" placeholder="Search name, phone or email"><span>{{rows.length}} suppliers</span></div><div class="scroll"><table><thead><tr><th>Supplier</th><th>Contact</th><th>Location</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="s in rows" :key="s.id"><td><b>{{s.name}}</b><small>{{s.company_name||'Individual supplier'}}</small></td><td>{{s.phone||s.email||'—'}}</td><td>{{[s.city,s.country].filter(Boolean).join(', ')||'—'}}</td><td><span :class="s.is_active?'active':'inactive'">{{s.is_active?'Active':'Inactive'}}</span></td><td><button class="light" @click="edit(s)">Edit</button></td></tr><tr v-if="!rows.length"><td colspan="5" class="empty">{{loading?'Loading...':'No suppliers found.'}}</td></tr></tbody></table></div></div><div v-if="show" class="overlay" @click.self="show=false"><form class="drawer" @submit.prevent="save"><div class="drawer-head"><div><small>SUPPLIER PROFILE</small><h2>{{editing?'Edit supplier':'Add supplier'}}</h2></div><button type="button" class="light" @click="show=false">✕</button></div><label>Name<input v-model="form.name" required></label><label>Company<input v-model="form.company_name"></label><div class="two"><label>Email<input v-model="form.email" type="email"></label><label>Phone<input v-model="form.phone"></label></div><div class="two"><label>Tax number<input v-model="form.tax_number"></label><label>City<input v-model="form.city"></label></div><label>Address<textarea v-model="form.address"></textarea></label><label>Notes<textarea v-model="form.notes"></textarea></label><label class="check"><input v-model="form.is_active" type="checkbox"> Active supplier</label><footer><button type="button" class="light" @click="show=false">Cancel</button><button type="submit">Save supplier</button></footer></form></div></section></template>
<style scoped>
.page{color:#172033}.page header,.drawer-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.page small,.drawer small{font-size:10px;letter-spacing:1.2px;color:#64748b;font-weight:800}.page h1{font-size:25px;margin:5px 0}.page p{font-size:13px;color:#7b8798}.page button{border:0;background:#172033;color:#fff;padding:10px 14px;border-radius:8px;cursor:pointer}.card{background:#fff;border:1px solid #e7ebf1;border-radius:13px;overflow:hidden}.filters{display:flex;justify-content:space-between;padding:15px}.filters input,input,textarea{border:1px solid #dfe5ed;border-radius:7px;padding:10px;font:inherit}.filters input{width:280px}.filters span,td,th{font-size:12px;color:#64748b}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:13px 15px;border-top:1px solid #edf0f4}th{background:#f8fafc;text-transform:uppercase;font-size:10px}td small{display:block;margin-top:4px}.active,.inactive{padding:5px 8px;border-radius:20px;background:#ecfdf5;color:#047857}.inactive{background:#f1f5f9;color:#64748b}.light{background:#fff!important;color:#334155!important;border:1px solid #dfe5ed!important}.empty{text-align:center;padding:30px}.overlay{position:fixed;inset:0;background:#0f172a66;display:flex;justify-content:flex-end;z-index:1000}.drawer{background:white;width:min(520px,100%);height:100%;overflow:auto;padding:25px;box-shadow:-10px 0 35px #0002}.drawer h2{margin:5px 0 0}.drawer label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:700;margin:13px 0}.drawer input,.drawer textarea{width:100%;box-sizing:border-box}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.drawer .check{flex-direction:row;align-items:center}.drawer .check input{width:auto}.drawer footer{display:flex;justify-content:flex-end;gap:10px;margin-top:22px}.error{color:#be123c}
</style>
